python3 << 'EOF'
import json
import numpy as np

data=json.load(open('network.json'))
rep=json.load(open('report.json'))
T=data['time_periods']; demand=data['demand']; R_req=data['reserves']
tg=data['thermal_generators']; rg=data['renewable_generators']

ok=True
def chk(name, cond, msg=''):
    global ok
    if not cond: ok=False; print('FAIL', name, msg)

u={}; p={}; r={}; y={}; z={}
for g in rep['thermal_generators']:
    n=g['name']; u[n]=np.array(g['commitment']); p[n]=np.array(g['production_MW'])
    r[n]=np.array(g['reserve_MW']); y[n]=np.array(g['startup']); z[n]=np.array(g['shutdown'])
ren={g['name']:np.array(g['production_MW']) for g in rep['renewable_generators']}

# H1 full form + D2 form
for n in tg:
    g=tg[n]; RU=g['ramp_up_limit']; RSU=g['ramp_startup_limit']
    on0=g['unit_on_t0']; p0=g['power_output_t0']
    prev_u=on0; prev_p=p0
    for t in range(T):
        cap = prev_p + RU*prev_u + RSU*y[n][t]
        chk('H1', p[n][t]+r[n][t] <= cap+1e-6, (n,t,p[n][t]+r[n][t],cap))
        if prev_u==1 and u[n][t]==1:
            chk('D2', p[n][t]+r[n][t] <= prev_p+RU+1e-6, (n,t))
        prev_u=u[n][t]; prev_p=p[n][t]

# startup tier ambiguity
def tier_cost(g, d):
    for tr in g['startup']:
        if d <= tr['lag']: return tr['cost']
    return g['startup'][-1]['cost']
amb=0
for n in tg:
    g=tg[n]
    if len(g['startup'])>1:
        cur=g['unit_on_t0']; off=g['time_down_t0'] if not g['unit_on_t0'] else 0
        for t in range(T):
            if u[n][t]==1 and cur==0:
                ca=tier_cost(g,off); cb=tier_cost(g,off+1)
                if ca!=cb: amb+=1; print('AMBIG', n, t, off)
            if u[n][t]==0: off+=1
            else: off=0
            cur=u[n][t]
chk('tier-ambiguity', amb==0, amb)

# balance, reserve, limits, ramping, minupdown, logic (from report only)
maxbal=0; maxshort=0
for t in range(T):
    th=sum(p[n][t] for n in tg); rr=sum(ren[n][t] for n in rg)
    maxbal=max(maxbal, abs(th+rr-demand[t]))
    maxshort=max(maxshort, max(0, R_req[t]-sum(r[n][t] for n in tg)))
chk('balance', maxbal<1e-4, maxbal)
chk('reserve', maxshort<1e-6, maxshort)
for n in tg:
    g=tg[n]; pmin=g['power_output_minimum']; pmax=g['power_output_maximum']
    if g['must_run']: chk('mustrun', np.all(u[n]==1), n)
    prev_u=g['unit_on_t0']; prev_p=g['power_output_t0']
    for t in range(T):
        if u[n][t]==0:
            chk('limits-off', abs(p[n][t])<1e-6 and r[n][t]<1e-6, (n,t))
        else:
            chk('limits', pmin-1e-6<=p[n][t]<=pmax+1e-6, (n,t))
        chk('headroom', p[n][t]+r[n][t]<=pmax*u[n][t]+1e-6, (n,t))
        chk('rcap', r[n][t]<=g['ramp_up_limit']+1e-6, (n,t))
        chk('logic', y[n][t]==(1 if u[n][t]>prev_u else 0) and z[n][t]==(1 if u[n][t]<prev_u else 0), (n,t))
        if prev_u==1 and u[n][t]==1:
            chk('ramp', p[n][t]-prev_p<=g['ramp_up_limit']+1e-6 and prev_p-p[n][t]<=g['ramp_down_limit']+1e-6, (n,t))
        elif prev_u==0 and u[n][t]==1:
            chk('ramp-su', p[n][t]<=pmin+g['ramp_startup_limit']+1e-6, (n,t))
        elif prev_u==1 and u[n][t]==0:
            chk('ramp-sd', prev_p<=pmin+g['ramp_shutdown_limit']+1e-6, (n,t))
        prev_u=u[n][t]; prev_p=p[n][t]
    cur=g['unit_on_t0']; since=g['time_up_t0'] if g['unit_on_t0'] else g['time_down_t0']
    for t in range(T):
        if cur==1 and u[n][t]==0:
            chk('minup', since>=g['time_up_minimum'], (n,t,since))
        if cur==0 and u[n][t]==1:
            chk('mindown', since>=g['time_down_minimum'], (n,t,since))
        if u[n][t]!=cur: since=0; cur=u[n][t]
        since+=1
for n in rg:
    g=rg[n]
    chk('ren-lim', np.all(ren[n]>=np.array(g['power_output_minimum'])-1e-6) and np.all(ren[n]<=np.array(g['power_output_maximum'])+1e-6), n)

# cost both conventions
cost_a=0.0; cost_b=0.0
for n in tg:
    g=tg[n]; pw=g['piecewise_production']
    xs=[q['mw'] for q in pw]; cs=[q['cost'] for q in pw]
    for t in range(T):
        if u[n][t]==1: cost_a+=np.interp(p[n][t],xs,cs); cost_b+=np.interp(p[n][t],xs,cs)
    cur=g['unit_on_t0']; off=0 if g['unit_on_t0'] else g['time_down_t0']
    for t in range(T):
        if cur==0:
            if u[n][t]==1:
                c1=None; c2=None
                for tr in g['startup']:
                    if off<=tr['lag'] and c1 is None: c1=tr['cost']
                    if off+1<=tr['lag'] and c2 is None: c2=tr['cost']
                if c1 is None: c1=g['startup'][-1]['cost']
                if c2 is None: c2=g['startup'][-1]['cost']
                cost_a+=c1; cost_b+=c2
                cur=1; off=0
            else: off+=1
        else:
            if u[n][t]==0: cur=0; off=1
print('cost_a=%.4f cost_b=%.4f report=%.4f' % (cost_a, cost_b, rep['summary']['objective_cost']))
chk('cost_a', abs(cost_a-rep['summary']['objective_cost'])<0.01)
chk('cost_b', abs(cost_b-rep['summary']['objective_cost'])<0.01)
chk('mipgap-consistent', abs(rep['summary']['objective_cost']-rep['summary']['objective_cost'])<1e-9)
print('status:', rep['summary']['solver_status'], 'gap:', rep['summary']['reported_mip_gap'])
print('startups:', rep['summary']['total_startups'], 'shutdowns:', rep['summary']['total_shutdowns'])
print('ALL OK' if ok else 'FAILURES PRESENT')
