import json
import numpy as np
data=json.load(open('network.json'))
T=data['time_periods']
tg=data['thermal_generators']

def load(fn):
    sol=json.load(open(fn))
    u=np.array(sol['u']); p=np.array(sol['p']); r=np.array(sol['r']); y=np.array(sol['y']); z=np.array(sol['z'])
    return sol['gnames'], u, p, r, y, z

def battery(gnames, u, p, r, y, z, label):
    print('===', label, '===')
    for name, cond in []:
        pass
    counts={}
    def vio(key):
        counts[key]=counts.get(key,0)+1
    for gi,n in enumerate(gnames):
        g=tg[n]; pmin=g['power_output_minimum']; pmax=g['power_output_maximum']
        RU=g['ramp_up_limit']; RD=g['ramp_down_limit']; RSU=g['ramp_startup_limit']; RSD=g['ramp_shutdown_limit']
        on0=g['unit_on_t0']; p0=g['power_output_t0']
        prev_u=on0; prev_p=p0
        for t in range(T):
            # ramps
            if prev_u==1 and u[gi,t]==1:
                if p[gi,t]-prev_p > RU+1e-6: vio('A1up')
                if prev_p-p[gi,t] > RD+1e-6: vio('A1dn')
            if prev_u==0 and u[gi,t]==1:
                if p[gi,t] > pmin+RSU+1e-6: vio('A2')
                if p[gi,t] > RSU+1e-6: vio('A3')
            if prev_u==1 and u[gi,t]==0:
                if prev_p > pmin+RSD+1e-6: vio('A4')
                if prev_p > RSD+1e-6: vio('A5')
            # blind ramps (prev_p = 0 if off)
            pp = prev_p if prev_u==1 else 0.0
            if p[gi,t]-pp > RU+1e-6: vio('A6')
            if pp-p[gi,t] > RD+1e-6: vio('A7')
            # reserve forms
            if p[gi,t]+r[gi,t] > pmax*u[gi,t]+1e-6: vio('B1')
            if r[gi,t] > RU+1e-6: vio('B2')
            cap3 = prev_p + RU*prev_u + RSU*y[gi,t]
            if p[gi,t]+r[gi,t] > cap3+1e-6: vio('B3')
            cap4 = pp + RU
            if p[gi,t]+r[gi,t] > cap4+1e-6: vio('B4')
            cap5 = prev_p + RU*prev_u + (pmin+RSU)*y[gi,t]
            if p[gi,t]+r[gi,t] > cap5+1e-6: vio('B5')
            prev_u=u[gi,t]; prev_p=p[gi,t]
    for k in sorted(counts): print(' ', k, counts[k])
    if not counts: print('  none')

gn,u,p,r,y,z = load('sol_raw.json')
battery(gn,u,p,r,y,z,'current (H1 model)')
